blueprints.compose:
services:
  n8n:
    image: n8nio/n8n:${IMAGE_TAG}
    environment:
      N8N_EDITOR_BASE_URL: ${N8N_URL}
      N8N_WEBHOOK_URL: ${N8N_URL}
      N8N_PROXY_HOPS: "1"
      N8N_ENCRYPTION_KEY: ${N8N_ENCRYPTION_KEY}
      GENERIC_TIMEZONE: ${GENERIC_TIMEZONE}
      TZ: ${GENERIC_TIMEZONE}
    volumes:
      - data:/home/node/.n8n
volumes:
  data:

services:
  mongo-express:
    image: mongo-express:${IMAGE_TAG}
    environment:
      ME_CONFIG_MONGODB_URL: ${MONGO_URL}
      # Without this, Mongo Express serves the database to anyone who finds the URL.
      ME_CONFIG_BASICAUTH_ENABLED: "true"
      ME_CONFIG_BASICAUTH_USERNAME: ${ME_CONFIG_BASICAUTH_USERNAME}
      ME_CONFIG_BASICAUTH_PASSWORD: ${ME_CONFIG_BASICAUTH_PASSWORD}
      ME_CONFIG_SITE_COOKIESECRET: ${ME_CONFIG_SITE_COOKIESECRET}
      ME_CONFIG_SITE_SESSIONSECRET: ${ME_CONFIG_SITE_SESSIONSECRET}
